def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            minr = min(y for y, x in cells)
            minc = min(x for y, x in cells)
            shape = frozenset((y - minr, x - minc) for y, x in cells)
            components.append((color, cells, shape))

    recolors = {}
    for color, cells, shape in components:
        if color == 1:
            for other_color, _, other_shape in components:
                if other_color != 1 and other_shape == shape:
                    recolors[color, tuple(cells)] = other_color
                    break

    out = [row[:] for row in grid]
    for color, cells, _ in components:
        if color == 1:
            new_color = next(
                (recolors[color, tuple(cells)] for _ in [0]
                 if (color, tuple(cells)) in recolors),
                color
            )
            for r, c in cells:
                out[r][c] = new_color
    return out
